insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('melanochromis-auratus','Auratus','Melanochromis auratus','malawi','fish','Orta','Agresif','Sarı-siyah çizgili; erişkin erkekleri koyulaşır. Güçlü bölgecilik gösterebildiğinden tank arkadaşları dikkatle seçilmelidir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul ağırlıklı hepçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Agresif, Kayalık"]]'::jsonb,array['auratus','melanochromis auratus','golden mbuna','sarı siyah ciklet']::text[],false,'published'),
('pseudotropheus-johannii','Johanni','Pseudotropheus johannii','malawi','fish','Orta','Agresif','Erkekleri mavi-siyah, dişileri turuncu tonlardadır. Erkekler arasında belirgin bölge rekabeti görülebilir.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul ağırlıklı hepçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Agresif, Renkli"]]'::jsonb,array['johanni','pseudotropheus johannii','mavi siyah ciklet','turuncu dişi']::text[],false,'published'),
('pseudotropheus-cyaneorhabdos','Maingano','Pseudotropheus cyaneorhabdos','malawi','fish','Orta','Yarı agresif','Mavi ve koyu yatay çizgileriyle tanınır. Johanni ile karıştırılabilir; tür ve varyete kimliği korunmalıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor; küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Bölgeci"]]'::jsonb,array['maingano','cyaneorhabdos','melanochromis maingano','mavi çizgili mbuna']::text[],false,'published'),
('pseudotropheus-socolofi','Powder Blue / Pindani','Pseudotropheus socolofi','malawi','fish','Orta','Yarı agresif','Pudra mavisi rengiyle bilinir. Görece daha ılımlı olsa da kaya bölgelerini savunabilir.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Otçul ağırlıklı hepçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Kayalık"]]'::jsonb,array['powder blue / pindani','socolofi','powder blue','pindani','mavi mbuna']::text[],false,'published'),
('pseudotropheus-elongatus','Elongatus Mbuna','Pseudotropheus elongatus','malawi','fish','Orta','Agresif','İnce ve uzun gövdelidir. Birden fazla form ve popülasyon adı kullanıldığı için kayıt düzeyinde kimlik doğrulaması önemlidir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul ağırlıklı hepçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Agresif, Kayalık"]]'::jsonb,array['elongatus mbuna','elongatus','pseudotropheus elongatus','ince gövdeli mbuna','kayalık ciklet']::text[],false,'published'),
('pseudotropheus-acei','Acei','Pseudotropheus acei','malawi','fish','Orta','Yarı agresif','Mavi-mor gövdesi ve sarı kuyruğuyla dikkat çeker. Genellikle grup hâlinde dolaşır ve birçok mbunaya göre daha sosyal olabilir.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['acei','pseudotropheus acei','sarı kuyruklu ciklet','mavi mbuna']::text[],false,'published'),
('pseudotropheus-crabro','Bumblebee','Pseudotropheus crabro','malawi','fish','Orta','Agresif','Sarı-siyah desenleriyle yaban arısını andırır. İri ve agresifleşebilen bir türdür; geniş alan gerekir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "300 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Agresif, İri Yapılı"]]'::jsonb,array['bumblebee','pseudotropheus crabro','arı cikleti','sarı siyah mbuna']::text[],false,'published'),
('iodotropheus-sprengerae','Rusty Cichlid','Iodotropheus sprengerae','malawi','fish','Orta','Yarı agresif','Pas rengi, kahverengi ve morumsu tonlarıyla klasik Malawi renk paletinden ayrılır. Görece küçük ve daha ılımlı bir mbunadır.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.8"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Barışçıl, Renkli"]]'::jsonb,array['rusty cichlid','iodotropheus sprengerae','pas rengi mbuna','mor ciklet']::text[],false,'published'),
('labeotropheus-trewavasae','Trewavas Cichlid','Labeotropheus trewavasae','malawi','fish','Orta','Agresif','Alg kazımaya uyumlu çıkıntılı burun yapısına sahiptir. Renk varyeteleri bulunur; farklı formlar karıştırılmamalıdır.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Otçul, Bölgeci"]]'::jsonb,array['trewavas cichlid','trewavasae','labeotropheus trewavasae','red top mbuna','kaya algi yiyen ciklet']::text[],false,'published'),
('labeotropheus-fuelleborni','Fuelleborn Cichlid','Labeotropheus fuelleborni','malawi','fish','Orta','Agresif','Güçlü gövdesi ve çıkıntılı üst dudağıyla tanınır. Bölgeci olabilir; bitkisel ağırlıklı beslenme uygundur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "300 L"], ["Huy", "Agresif"], ["Beslenme", "Otçul ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Otçul, İri Yapılı"]]'::jsonb,array['fuelleborn cichlid','fuelleborni','labeotropheus fuelleborni','orange blotch','turuncu benekli mbuna']::text[],false,'published'),
('cynotilapia-afra','Afra Cichlid','Cynotilapia afra','malawi','fish','Orta','Agresif','Dikey bantları ve mavi tonlarıyla bilinir. Çok sayıda coğrafi renk formu vardır; farklı formlar karıştırılmamalıdır.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "200 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Bölgeci"]]'::jsonb,array['afra cichlid','afra','cynotilapia afra','dogtooth cichlid','çizgili mbuna']::text[],false,'published'),
('labidochromis-chisumulae','Chisumulu Cichlid','Labidochromis chisumulae','malawi','fish','Orta','Yarı agresif','Chizumulu Adası çevresine özgü, açık mavi tonları ve koyu bantlarıyla tanınan küçük bir mbunadır.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Küçük Yapılı, Kayalık"]]'::jsonb,array['chisumulae','labidochromis chisumulae','chisumulu cichlid','açık mavi mbuna']::text[],true,'published'),
('pseudotropheus-tropheops','Tropheops','Pseudotropheus tropheops','malawi','fish','Orta','Yarı agresif–agresif','Kaya yüzeylerinde beslenen; görünümü popülasyona göre değişebilen bir mbuna grubudur. Tür ve varyete karışıklığından kaçınılmalıdır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Otçul ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Otçul, Bölgeci"]]'::jsonb,array['tropheops','pseudotropheus tropheops','tropheops mbuna','kaya cikleti']::text[],false,'published'),
('metriaclima-lombardoi','Kenyi','Metriaclima lombardoi','malawi','fish','Zor','Çok agresif','Gençler ve dişiler çoğunlukla sarı, baskın erkekler mavi tonlardadır. Çok agresif ve bölgeci olabilir.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "300 L"], ["Huy", "Çok agresif"], ["Beslenme", "Otçul ağırlıklı hepçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Agresif, Renk Değiştiren"]]'::jsonb,array['kenyi','metriaclima lombardoi','sarı mavi ciklet','kenyi mbuna']::text[],false,'published'),
('metriaclima-greshakei','Red Top Ice Blue','Metriaclima greshakei','malawi','fish','Orta','Yarı agresif–agresif','Mavi gövdesi ve kızıl-turuncu sırt yüzgeciyle tanınır. Bölgecilik gösterebilir; bitkisel ağırlıklı beslenmelidir.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.6"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Otçul ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Kayalık"]]'::jsonb,array['greshakei','metriaclima greshakei','red top ice blue','kırmızı sırt yüzgeçli mbuna']::text[],false,'published'),
('sciaenochromis-fryeri','Electric Blue Hap','Sciaenochromis fryeri','malawi','fish','Zor','Yarı agresif, avcı','Erkekleri elektrik mavisi rengiyle öne çıkan bir avcıdır. Küçük balıkları avlayabilir; tank arkadaşlarının boyutu dikkatle seçilmelidir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "400 L"], ["Huy", "Yarı agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, Renkli"]]'::jsonb,array['electric blue hap','sciaenochromis fryeri','ahli','mavi hap']::text[],false,'published'),
('cyrtocara-moorii','Mavi Yunus','Cyrtocara moorii','malawi','fish','Zor','Barışçıl–yarı agresif','Mavi gövdesi ve erişkin erkeklerde belirginleşebilen alın çıkıntısıyla tanınır. Kumluk alanları ve geniş yüzme alanını tercih eder.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "7.5–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor, omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "İri Yapılı, Barışçıl"]]'::jsonb,array['mavi yunus','cyrtocara moorii','blue dolphin','alın çıkıntılı ciklet']::text[],false,'published'),
('copadichromis-borleyi','Kadango Red Fin','Copadichromis borleyi','malawi','fish','Zor','Yarı agresif','Erkekleri mavi tonları ve kırmızı-turuncu yüzgeçleriyle dikkat çeker. Açık su ve kum-kaya geçişlerinde yaşayan, yüzme alanı isteyen bir türdür.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–8.6"], ["Min. akvaryum", "400 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Plankton ve küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Sürü Balığı, Renkli"]]'::jsonb,array['kadango red fin','kadango','copadichromis borleyi','red fin','kırmızı yüzgeçli hap']::text[],false,'published'),
('placidochromis-electra','Deepwater Hap','Placidochromis electra','malawi','fish','Kolay','Barışçıl–yarı agresif','Mavi tonları ve koyu yatay bantlarıyla bilinir. Genellikle kumluk alanlarda yaşar; benzer karakterli türlerle daha uygun eşleşir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "350 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Barışçıl, Açık Su"]]'::jsonb,array['placidochromis electra','deepwater hap','electra ciklet','mavi hap']::text[],true,'published'),
('nimbochromis-livingstonii','Livingstonii','Nimbochromis livingstonii','malawi','fish','Zor','Avcı, yarı agresif','Düzensiz koyu lekeleriyle ayırt edilir. Pusu kuran iri bir avcıdır ve küçük balıklarla tutulmamalıdır.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Avcı, yarı agresif"], ["Beslenme", "Etçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, İri Yapılı"]]'::jsonb,array['livingstonii','nimbochromis livingstonii','kaligono','benekli avcı ciklet']::text[],false,'published'),
('nimbochromis-venustus','Venustus','Nimbochromis venustus','malawi','fish','Zor','Avcı, yarı agresif','Zürafa desenini andıran lekeleri ve erişkin erkeklerde mavi-sarı renkleriyle tanınır. Büyük boyutlu bir avcıdır.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Avcı, yarı agresif"], ["Beslenme", "Etçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, Renkli"]]'::jsonb,array['venustus','nimbochromis venustus','giraffe hap','zürafa ciklet']::text[],false,'published'),
('protomelas-taeniolatus','Red Empress','Protomelas taeniolatus','malawi','fish','Zor','Yarı agresif','Erkeklerinde kırmızı, turuncu ve mavi renkler görülebilir. Ticari adla satılan formlar farklılık gösterebildiği için kimlik doğrulaması önemlidir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "400 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel ve omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Açık Su"]]'::jsonb,array['red empress','protomelas taeniolatus','super red empress','kırmızı mavi hap']::text[],false,'published'),
('otopharynx-lithobates','Sulphur Head Hap','Otopharynx lithobates','malawi','fish','Orta','Yarı agresif','Erkeklerinde sarı-turuncu baş ve mavi gövde görülebilir. Kayalık alanlarla ilişkili, dikkat çekici bir türdür.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Kayalık"]]'::jsonb,array['otopharynx lithobates','sulphur head hap','sarı başlı hap','mavi sarı ciklet']::text[],true,'published'),
('dimidiochromis-compressiceps','Eye-Biter','Dimidiochromis compressiceps','malawi','fish','Zor','Avcı','Yanlardan basık uzun gövdesiyle ayırt edilir. Bitkiler arasında pusu kuran bir avcıdır; küçük balıklarla tutulmamalıdır.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.5–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Avcı"], ["Beslenme", "Etçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, Uzun Gövdeli"]]'::jsonb,array['eye-biter','dimidiochromis compressiceps','eye biter','göz avcısı','uzun gövdeli ciklet']::text[],true,'published'),
('fossorochromis-rostratus','Fossorochromis','Fossorochromis rostratus','malawi','fish','Zor','Yarı agresif','Kum tabakasını eşeleyerek besin arayan, hızlı yüzen ve iri büyüyen bir türdür. İnce kum ve geniş açık alan gerektirir.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "7.5–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, kumdan çıkarılan omurgasızlar"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Kum Eleyen, İri Yapılı"]]'::jsonb,array['fossorochromis','fossorochromis rostratus','kum eleyen ciklet','rostratus','kumluk alan türü']::text[],true,'published'),
('aristochromis-christyi','Aristochromis','Aristochromis christyi','malawi','fish','Zor','Avcı','Uzun başı ve avcı ağız yapısıyla tanınan, büyük boyutlara ulaşabilen bir Malawi yırtıcısıdır. Geniş hacim ve uygun büyüklükte tank arkadaşları gerekir.','[["Yetişkin boy", "28 cm"], ["Sıcaklık", "24–26 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "700 L"], ["Huy", "Avcı"], ["Beslenme", "Etçil"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, Nadir Tür"]]'::jsonb,array['aristochromis christyi','aristochromis','büyük malawi avcısı','christyi ciklet']::text[],true,'published'),
('placidochromis-milomo','Super VC 10','Placidochromis milomo','malawi','fish','Zor','Yarı agresif','Kalın dudaklarıyla tanınır; bu özellik doğal bireylerde daha belirgin olabilir. İri yapılı ve özel görünüşlü bir Malawi türüdür.','[["Yetişkin boy", "23 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.6–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "İri Yapılı, Özel Görünüm"]]'::jsonb,array['placidochromis milomo','super vc 10','kalın dudaklı hap','milomo ciklet']::text[],true,'published'),
('aulonocara-baenschi','Sunshine Peacock','Aulonocara baenschi','malawi','fish','Orta','Yarı agresif','Erkeklerinde sarı ve mavi tonları görülen, sınırlı yayılışlı bir tavus kuşu cikletidir. Kumluk-kayalık geçiş bölgelerinde yaşar.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Kumluk Alan"]]'::jsonb,array['aulonocara baenschi','sunshine peacock','yellow regal','sarı tavus kuşu']::text[],true,'published'),
('aulonocara-stuartgranti','Stuartgranti Peacock','Aulonocara stuartgranti','malawi','fish','Orta','Yarı agresif','Mavi, sarı ve metalik renkler coğrafi popülasyona göre değişebilir. Satış kaydında mümkünse varyete veya toplama bölgesi belirtilmelidir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Renkli, Kumluk Alan"]]'::jsonb,array['aulonocara stuartgranti','stuartgranti peacock','mavi peacock','tavus kuşu ciklet']::text[],false,'published'),
('aulonocara-ethelwynnae','Northern Aulonocara','Aulonocara ethelwynnae','malawi','fish','Orta','Yarı agresif','Malawi Gölü''nün kuzeyindeki sınırlı yayılışıyla bilinen bir tavus kuşu cikletidir. Standart ticari formların dışında tür arayan hobicilere hitap eder.','[["Yetişkin boy", "11 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "7.4–9.0"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Nadir Tür, Renkli"]]'::jsonb,array['aulonocara ethelwynnae','northern aulonocara','kuzey peacock','nadir aulonocara']::text[],true,'published'),
('buccochromis-nototaenia','Stripeback Hap','Buccochromis nototaenia','malawi','fish','Zor','Yarı agresif, avcı','Açık sularda yaşayan iri ve avcı bir Malawi cikletidir. Yetişkin boyu nedeniyle büyük akvaryum ve dikkatli eşleştirme gerektirir.','[["Yetişkin boy", "22 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.5–8.8"], ["Min. akvaryum", "500 L"], ["Huy", "Yarı agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Malawi Gölü"], ["Özellikler", "Avcı, İri Yapılı"]]'::jsonb,array['buccochromis nototaenia','stripeback hap','gold nkanda','büyük malawi cikleti']::text[],true,'published')
